<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { adminServices } from '../services/AdminServices';
import { RepositoryError } from '../repository/RepositoryError';
import type { CatalogItem, CatalogFilter } from '../repository/CatalogRepository';
import { Category, ContestLevel, CreditApplicable, ChangeType, VersionStatus, type ContestPayload, type ContestVersion, type UpdateDraftRequest } from '../models/contracts';
const props=defineProps<{openContestId?:string}>();
const emit=defineEmits<{ 'session-expired':[];'import-file':[contestId:string] }>();
const repo=adminServices.getCatalog(),session=adminServices.getSession();
const rows=ref<CatalogItem[]>([]),keyword=ref(''),level=ref<ContestLevel|''>(''),state=ref<VersionStatus|''>(''),page=ref(1),total=ref(0),loading=ref(false),error=ref('');
const opened=ref(false),busy=ref(false),item=ref<CatalogItem|null>(null),form=ref<ContestPayload|null>(null),organizer=ref(''),reason=ref('目录资料补充'),changeType=ref(ChangeType.Value1),editorError=ref(''),fieldErrors=ref<Record<string,string>>({}),baseline=ref('');
let generation=0,detailGeneration=0,alive=true;
onBeforeUnmount(()=>{alive=false;generation++;detailGeneration++;});
const effective=computed<ContestVersion|null>(()=>item.value?.workingVersion||item.value?.publishedVersion||null);
const isCatalog=computed(()=>!!item.value?.sourceRows?.length);
const editable=computed(()=>!!item.value?.workingVersion&&[VersionStatus.Value0,VersionStatus.Value3].includes(item.value.workingVersion.status));
const signature=()=>JSON.stringify([form.value,organizer.value,reason.value,changeType.value]);
const dirty=computed(()=>form.value!==null&&signature()!==baseline.value);
type TextKey='name'|'edition'|'contact'|'description'|'sourceTitle'|'sourceOrg'|'sourceUrl'|'creditBasis'|'creditNote'|'entryMethod'|'contestRequirement'|'reviewRules'|'awardSetting'|'material';
type DateKey='regStart'|'regEnd'|'contestStart'|'contestEnd'|'publicityTime'|'sourcePublishedAt'|'lastVerifiedAt';
const basics: {key:TextKey;label:string;max?:number;rows?:number}[]=[{key:'name',label:'赛事名称',max:100},{key:'edition',label:'赛事届次'},{key:'contact',label:'联系方式'},{key:'description',label:'简介与来源说明（目录赛事保留【赛事目录条目】标记）',rows:8}];
const content: {key:TextKey;label:string;max?:number;rows?:number}[]=[{key:'contestRequirement',label:'参赛要求',max:2000,rows:4},{key:'material',label:'参赛材料',rows:3},{key:'reviewRules',label:'评审规则',max:4000,rows:4},{key:'awardSetting',label:'奖项设置',max:3000,rows:4},{key:'entryMethod',label:'报名方式',rows:3}];
const sources:{key:TextKey;label:string;rows?:number}[]=[{key:'sourceTitle',label:'来源标题'},{key:'sourceOrg',label:'来源发布单位'},{key:'sourceUrl',label:'原通知链接（HTTP/HTTPS）'}];
const dates:{key:DateKey;label:string}[]=[{key:'regStart',label:'报名开始'},{key:'regEnd',label:'报名截止'},{key:'contestStart',label:'比赛开始'},{key:'contestEnd',label:'比赛结束'},{key:'publicityTime',label:'公示时间'}];
function copy<T>(v:T):T{return JSON.parse(JSON.stringify(v)) as T;}
function payload(row:CatalogItem):ContestPayload|null{return (row.workingVersion||row.publishedVersion)?.payload||null;}
function setText(key:TextKey,value:string){if(!form.value)return;const text=value||'';if(key==='name'||key==='entryMethod')form.value[key]=text;else form.value[key]=text.trim()?text:null;}
function setDate(key:DateKey,value:string){if(!form.value)return;if(key==='lastVerifiedAt')form.value.lastVerifiedAt=value.trim();else form.value[key]=value.trim()||null;}
function errorText(e:unknown):string{if(e instanceof RepositoryError){if(e.code===401){session.invalidate();emit('session-expired');}if(e.code===409)return e.message+'；你的输入已保留，请重新载入核对。';return e.message;}return e instanceof Error?e.message:'操作失败，请重试';}
async function guard(){if(await session.check())return true;emit('session-expired');return false;}
async function load(next=1){const id=++generation;loading.value=true;error.value='';try{if(!await guard())return;const filter:CatalogFilter={keyword:keyword.value.trim()||undefined,level:level.value||undefined,state:state.value||undefined,page:next,pageSize:20};const result=await repo.list(filter);if(!alive||id!==generation)return;rows.value=result.list;total.value=result.total;page.value=next;}catch(e){if(id===generation)error.value=errorText(e);}finally{if(id===generation)loading.value=false;}}
function install(value:CatalogItem){item.value=value;const v=value.workingVersion||value.publishedVersion;form.value=v?copy(v.payload):null;organizer.value=value.organizationName.replace(/（目录记载，未认证）$/,'');reason.value=value.workingVersion?.reason||'目录资料补充';changeType.value=value.workingVersion?.changeType||ChangeType.Value1;baseline.value=signature();fieldErrors.value={};editorError.value='';}
async function open(row:CatalogItem){const id=++detailGeneration;opened.value=true;busy.value=true;item.value=null;form.value=null;editorError.value='';try{if(!await guard())return;const result=await repo.get(row.contest.contestId);if(alive&&id===detailGeneration&&opened.value)install(result);}catch(e){editorError.value=errorText(e);}finally{if(id===detailGeneration)busy.value=false;}}
async function reload(){if(!item.value||busy.value)return;if(dirty.value){try{await ElMessageBox.confirm('重新载入会丢弃未保存的输入，是否继续？','重新载入');}catch{return;}}await open(item.value);}
async function close(){if(busy.value)return;if(dirty.value){try{await ElMessageBox.confirm('当前输入尚未保存，确认关闭？','关闭编辑');}catch{return;}}opened.value=false;detailGeneration++;}
function showFailure(e:unknown){editorError.value=errorText(e);fieldErrors.value=e instanceof RepositoryError?e.details?.fieldErrors||{}:{};}
async function derive(){if(busy.value||!item.value?.publishedVersion||item.value.workingVersion)return;if(!reason.value.trim()){editorError.value='填写修改原因后再创建草稿';return;}busy.value=true;try{if(!await guard())return;const id=item.value.contest.contestId;await repo.derive(id,{changeType:changeType.value,reason:reason.value.trim()},{ifMatch:item.value.publishedVersion.etag});install(await repo.get(id));ElMessage.success('修改草稿已创建，学生端仍显示原公开版本');await load(page.value);}catch(e){showFailure(e);}finally{busy.value=false;}}
async function save(){if(busy.value||!editable.value||!item.value?.workingVersion||!form.value)return;if(!reason.value.trim()||!form.value.name.trim()||!organizer.value.trim()){editorError.value='赛事名称、主办方和修改原因必填';return;}busy.value=true;fieldErrors.value={};try{if(!await guard())return;const id=item.value.contest.contestId,v=item.value.workingVersion;const draft:UpdateDraftRequest={...copy(form.value),changeType:changeType.value,reason:reason.value.trim()};await repo.save(id,v.versionId,{draft,organizerName:organizer.value.trim()},{ifMatch:v.etag});install(await repo.get(id));ElMessage.success('草稿已保存，尚未改变学生端公开内容');await load(page.value);}catch(e){showFailure(e);}finally{busy.value=false;}}
async function submit(){if(busy.value||!editable.value||!item.value?.workingVersion)return;if(dirty.value){editorError.value='请先保存草稿，再提交审核';return;}try{await ElMessageBox.confirm('提交后草稿将只读；审核通过前学生端继续显示原版本。','提交目录审核');}catch{return;}busy.value=true;try{if(!await guard())return;const id=item.value.contest.contestId,v=item.value.workingVersion;await repo.submit(id,{versionId:v.versionId,etag:v.etag});install(await repo.get(id));ElMessage.success('已提交，请在赛事审核中查看并审核');await load(page.value);}catch(e){showFailure(e);}finally{busy.value=false;}}
onMounted(()=>load());
watch(()=>props.openContestId,async id=>{if(!id)return;try{const row=await repo.get(id);if(alive)await open(row);}catch(e){error.value=errorText(e);}},{immediate:true});
</script>
<template>
 <section class="catalog-panel">
  <el-alert title="维护当前工作高校的赛事。负责人仅能查看分配给自己的赛事；保存草稿不更新学生端，审核通过才公开。" type="info" :closable="false" />
  <div class="catalog-toolbar"><el-input v-model="keyword" placeholder="搜索目录赛事名称" clearable @keyup.enter="load()" /><el-select v-model="level" placeholder="全部层级" clearable @change="load()"><el-option label="国家级" :value="ContestLevel.Value2"/><el-option label="省级" :value="ContestLevel.Value1"/></el-select><el-select v-model="state" placeholder="全部版本状态" clearable @change="load()"><el-option v-for="s in Object.values(VersionStatus)" :key="s" :label="s" :value="s"/></el-select><el-button @click="load(page)" :loading="loading">查询 / 刷新</el-button><span>共 {{total}} 条</span></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" />
  <el-table :data="rows" v-loading="loading" empty-text="暂无可维护赛事；负责人需先由校级管理员分配赛事">
   <el-table-column label="赛事" min-width="230"><template #default="{row}">{{payload(row)?.name}}</template></el-table-column><el-table-column label="层级" width="85"><template #default="{row}">{{payload(row)?.level}}</template></el-table-column><el-table-column prop="organizationName" label="主办方" min-width="190"/><el-table-column label="状态" width="110"><template #default="{row}">{{(row.workingVersion||row.publishedVersion)?.status}}</template></el-table-column><el-table-column label="公开版本" width="100"><template #default="{row}">{{row.publishedVersion ? 'v'+row.publishedVersion.versionNo : '未公开'}}</template></el-table-column><el-table-column label="资料" width="95"><template #default="{row}">{{payload(row)?.completeness}}</template></el-table-column><el-table-column label="操作" width="210"><template #default="{row}"><el-button link type="primary" @click="open(row)">查看 / 编辑</el-button><el-button link type="primary" :disabled="!!row.workingVersion||!row.publishedVersion||!!row.contest.takedown" @click="emit('import-file',row.contest.contestId)">从文件补充</el-button></template></el-table-column>
  </el-table>
  <el-pagination class="catalog-space" background layout="prev, pager, next, total" :total="total" :page-size="20" :current-page="page" :disabled="loading" @current-change="load" />
  <el-dialog :model-value="opened" @update:model-value="close" title="赛事资料维护" width="min(1050px,94%)" :close-on-click-modal="false" :close-on-press-escape="false" :show-close="!busy">
   <div v-loading="busy"><el-alert v-if="editorError" :title="editorError" type="error" :closable="false"/><ul v-if="Object.keys(fieldErrors).length" class="field-errors"><li v-for="(msg,key) in fieldErrors" :key="key">{{key}}：{{msg}}</li></ul>
    <template v-if="item && form"><p>公开版本：{{item.publishedVersion?.versionNo||'无'}}　当前查看：v{{effective?.versionNo}} · {{effective?.status}}</p>
     <el-alert v-if="effective?.status===VersionStatus.Value1" title="此版本正在审核，暂不能编辑；可到赛事审核中通过或驳回。" type="warning" :closable="false"/>
     <el-form label-position="top" class="catalog-form">
      <div class="catalog-grid"><el-form-item label="修改原因（必填）"><el-input v-model="reason" :disabled="busy||effective?.status===VersionStatus.Value1" maxlength="2000" /></el-form-item><el-form-item label="变更类型"><el-select v-model="changeType" :disabled="busy||effective?.status===VersionStatus.Value1"><el-option v-for="s in Object.values(ChangeType)" :key="s" :label="s" :value="s"/></el-select></el-form-item></div>
      <fieldset :disabled="!editable||busy"><legend>基本信息</legend>
       <el-form-item v-for="f in basics" :key="f.key" :label="f.label"><el-input :model-value="form[f.key]??''" @update:model-value="setText(f.key,$event)" :type="f.rows?'textarea':'text'" :rows="f.rows" :maxlength="f.max" :disabled="!editable||busy" /></el-form-item>
       <div class="catalog-grid"><el-form-item label="主办方（必填；修改不会改动其他赛事）"><el-input v-model="organizer" maxlength="300" :disabled="!editable||busy"/></el-form-item><el-form-item label="层级"><el-select v-model="form.level" :disabled="!editable||busy"><el-option label="国家级" :value="ContestLevel.Value2"/><el-option label="省级" :value="ContestLevel.Value1"/></el-select></el-form-item><el-form-item label="分类"><el-select v-model="form.category" :disabled="!editable||busy"><el-option v-for="s in Object.values(Category)" :key="s" :label="s" :value="s"/></el-select></el-form-item></div>
       <el-form-item label="适用对象说明（学院、专业、年级、学历、校区等）"><el-input v-model="form.applicableScope.applicableNote" type="textarea" :rows="4" :disabled="!editable||busy"/></el-form-item>
      </fieldset>
      <fieldset><legend>时间安排</legend><p class="muted">未知日期留空。支持 YYYY-MM-DD；有明确时刻时填 YYYY-MM-DDTHH:mm:ss+08:00。补充日期时须填写原通知链接、来源单位和核对日期。非目录赛事提交时还须补齐普通赛事的必填资料。</p><div class="catalog-grid"><el-form-item v-for="f in dates" :key="f.key" :label="f.label"><el-input :model-value="form[f.key]??''" @update:model-value="setDate(f.key,$event)" clearable placeholder="未知留空，不推测日期" :disabled="!editable||busy"/></el-form-item></div></fieldset>
      <fieldset><legend>分阶段日程（初赛、作品提交等）</legend><p class="muted">单个阶段结束不代表整项赛事结束。时刻统一使用北京时间；每项保留正式通知链接。</p><div v-for="(stage,index) in form.schedule||[]" :key="index" class="catalog-grid"><el-form-item label="阶段"><el-input v-model="stage.stage" :disabled="!editable||busy"/></el-form-item><el-form-item label="日期或带时区时刻"><el-input v-model="stage.value" :disabled="!editable||busy"/></el-form-item><el-form-item label="官方来源"><el-input v-model="stage.sourceUrl" :disabled="!editable||busy"/></el-form-item><el-button @click="form.schedule?.splice(index,1)" :disabled="!editable||busy">删除阶段</el-button></div><el-button @click="form.schedule=(form.schedule||[]).concat([{stage:'',value:'',sourceUrl:form.sourceUrl||''}])" :disabled="!editable||busy">添加阶段</el-button></fieldset><fieldset><legend>参赛与奖项</legend><el-form-item v-for="f in content" :key="f.key" :label="f.label"><el-input :model-value="form[f.key]??''" @update:model-value="setText(f.key,$event)" type="textarea" :rows="f.rows" :maxlength="f.max" :disabled="!editable||busy"/></el-form-item><el-form-item label="第二课堂是否适用"><el-select v-model="form.creditApplicable" :disabled="!editable||busy"><el-option v-for="s in Object.values(CreditApplicable)" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="认定依据（适用时必填）"><el-input :model-value="form.creditBasis??''" @update:model-value="setText('creditBasis',$event)" type="textarea" :disabled="!editable||busy"/></el-form-item><el-form-item label="第二课堂说明（待确认时必填）"><el-input :model-value="form.creditNote??''" @update:model-value="setText('creditNote',$event)" type="textarea" :disabled="!editable||busy"/></el-form-item></fieldset>
      <fieldset><legend>来源与核对</legend><el-form-item v-for="f in sources" :key="f.key" :label="f.label"><el-input :model-value="form[f.key]??''" @update:model-value="setText(f.key,$event)" :disabled="!editable||busy"/></el-form-item><div class="catalog-grid"><el-form-item label="原文发布日期（未知留空）"><el-input :model-value="form.sourcePublishedAt??''" @update:model-value="setDate('sourcePublishedAt',$event)" :disabled="!editable||busy"/></el-form-item><el-form-item label="最近核对日期（实际核对后填写）"><el-input :model-value="form.lastVerifiedAt" @update:model-value="setDate('lastVerifiedAt',$event)" placeholder="YYYY-MM-DD" :disabled="!editable||busy"/></el-form-item></div></fieldset>
     </el-form>
     <el-collapse v-if="isCatalog"><el-collapse-item title="原Excel记录（只读，编辑不会改写原始行）"><section v-for="source in item.sourceRows||[]" :key="source.sheet+source.excelRow"><h4>{{source.sheet}} · 序号{{source.serial}} · 行{{source.excelRow}}</h4><el-table :data="Object.entries(source.raw).map(([key,value])=>({key,value}))"><el-table-column prop="key" label="原字段" width="160"/><el-table-column prop="value" label="原始内容"/></el-table></section></el-collapse-item></el-collapse>
    </template>
   </div><template #footer><el-button @click="close" :disabled="busy">关闭</el-button><el-button @click="reload" :disabled="busy||!item">重新载入</el-button><el-button v-if="item&&!item.workingVersion&&item.publishedVersion" type="primary" @click="derive" :loading="busy">创建修改草稿</el-button><template v-if="editable"><el-button type="primary" @click="save" :loading="busy">保存草稿</el-button><el-button type="success" @click="submit" :disabled="busy||dirty">提交审核</el-button></template></template>
  </el-dialog>
 </section>
</template>
<style scoped>
.catalog-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:18px 0}.catalog-toolbar .el-input{max-width:300px}.catalog-toolbar .el-select{width:160px}.catalog-space{margin-top:20px}.catalog-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.catalog-form{margin-top:20px}fieldset{border:1px solid #e2e8f0;border-radius:10px;margin:16px 0;padding:18px}legend{padding:0 8px;font-weight:600}.muted{color:#64748b;font-size:13px}.field-errors{color:#b42318}.catalog-panel :deep(.el-select){width:100%}.catalog-toolbar :deep(.el-select){width:160px}@media(max-width:700px){.catalog-grid{grid-template-columns:1fr}}
</style>
